SELECT FROM lantu_web_dsn.posts p LEFT JOIN lantu_web.users u ON p.user_id = u.id LEFT JOIN lantu_web.user_avatars ua ON p.user_id = ua.user_id WHERE p.status = 1
AND p.category = #{category}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.created_at DESC, p.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM lantu_web_dsn.posts p WHERE p.status = 1
AND p.category = #{category}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
